// Allowlist these AI agent user-agents in your WAF/CDN config:
// GPTBot, ChatGPT-User, OAI-SearchBot (OpenAI)
// Claude-User, Claude-SearchBot, anthropic-ai (Anthropic)
// PerplexityBot, Google-Extended, Bravebot, DuckAssistBot

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What is your return policy?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We offer a 30-day money-back guarantee on all purchases."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "Service",
  "name": "Your Service Name",
  "description": "A clear description of what this service provides.",
  "provider": {
    "@type": "Organization",
    "name": "Your Company"
  }
}

{
  "@context": "https://schema.org",
  "@type": "HowTo",
  "name": "How to set up your account",
  "step": [
    { "@type": "HowToStep", "name": "Create an account", "text": "Visit the signup page and fill in your details." },
    { "@type": "HowToStep", "name": "Verify your email", "text": "Click the link in the confirmation email." }
  ]
}

// /openapi.json
{
  "openapi": "3.0.3",
  "info": {
    "title": "Your Site API",
    "version": "1.0.0",
    "x-ai-instructions": "Use this API to interact with Your Site."
  },
  "servers": [{ "url": "https://yoursite.com/api" }],
  "paths": {
    "/contact": {
      "post": {
        "operationId": "submitContact",
        "summary": "Submit a contact inquiry",
        "requestBody": {
          "content": {
            "application/json": {
              "schema": {
                "type": "object",
                "properties": {
                  "name": { "type": "string" },
                  "email": { "type": "string" },
                  "message": { "type": "string" }
                }
              }
            }
          }
        },
        "responses": { "200": { "description": "Success" } }
      }
    }
  }
}

"info": {
  "title": "Your Site API",
  "version": "1.0.0",
  "x-ai-instructions": "This API lets you search content, submit contact forms, and retrieve product details. Always call searchContent before submitContact. Rate limit: 10 requests/minute. No authentication required for read endpoints."
}

// /.well-known/ai-catalog.json
{
  "version": "1.0",
  "name": "Your Site",
  "description": "What your site does",
  "capabilities": ["search", "contact", "product-info"],
  "services": [
    {
      "name": "Search",
      "description": "Search our content",
      "url": "https://yoursite.com/api/search",
      "type": "rest"
    }
  ]
}

// /.well-known/agents.json
{
  "name": "Your Site",
  "description": "Your site description for AI agents",
  "protocols": ["rest", "mcp"],
  "authentication": { "type": "none" },
  "rate_limits": { "requests_per_minute": 60 },
  "endpoints": [
    {
      "url": "/api/search",
      "method": "GET",
      "description": "Search content"
    }
  ]
}

// /.well-known/ai-plugin.json
{
  "schema_version": "v1",
  "name_for_human": "Your Site Name",
  "name_for_model": "your_site",
  "description_for_human": "What your site does for users.",
  "description_for_model": "Use this plugin to search content and submit inquiries.",
  "auth": { "type": "none" },
  "api": {
    "type": "openapi",
    "url": "https://yoursite.com/openapi.json"
  },
  "logo_url": "https://yoursite.com/logo.png",
  "contact_email": "hello@yoursite.com"
}

// /.well-known/mcp/servers.json
{
  "servers": [
    {
      "name": "Your Site MCP",
      "description": "Search content and submit inquiries",
      "url": "https://yoursite.com/mcp",
      "transport": "streamable-http",
      "capabilities": {
        "tools": true,
        "resources": true
      }
    }
  ]
}

// Expected request:
POST /mcp
Content-Type: application/json

{
  "jsonrpc": "2.0",
  "id": 1,
  "method": "initialize",
  "params": {
    "protocolVersion": "2024-11-05",
    "capabilities": {},
    "clientInfo": { "name": "test", "version": "1.0.0" }
  }
}

// Expected response:
{
  "jsonrpc": "2.0",
  "id": 1,
  "result": {
    "protocolVersion": "2024-11-05",
    "serverInfo": { "name": "your-server", "version": "1.0.0" },
    "capabilities": { "tools": {} }
  }
}

// /.well-known/webmcp
{
  "name": "Your Store",
  "description": "E-commerce store with product search and checkout",
  "tools": [
    {
      "name": "searchProducts",
      "description": "Search the product catalog by keyword, category, or filters",
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": { "type": "string", "description": "Search keywords" },
          "category": { "type": "string", "description": "Product category" }
        },
        "required": ["query"]
      }
    }
  ]
}

// In /.well-known/webmcp manifest
{
  "tools": [
    {
      "name": "searchProducts",
      "description": "Search the product catalog",
      "annotations": {
        "readOnlyHint": true,
        "destructiveHint": false,
        "idempotentHint": true
      },
      "inputSchema": { ... }
    },
    {
      "name": "addToCart",
      "description": "Add a product to the cart",
      "annotations": {
        "readOnlyHint": false,
        "destructiveHint": false,
        "idempotentHint": false
      },
      "inputSchema": { ... }
    }
  ]
}

<!-- Or on declarative forms -->
<form toolname="addToCart"
      tooldescription="Add a product to the shopping cart"
      data-readonly="false"
      data-destructive="false">

// /.well-known/webmcp — full commerce coverage
{
  "tools": [
    {
      "name": "searchProducts",
      "description": "Search the product catalog by keyword, category, or filters",
      "annotations": { "readOnlyHint": true },
      "inputSchema": {
        "type": "object",
        "properties": {
          "query": { "type": "string" },
          "category": { "type": "string" },
          "maxPrice": { "type": "number" }
        },
        "required": ["query"]
      }
    },
    {
      "name": "getProductDetails",
      "description": "Get full details for a specific product by ID or URL",
      "annotations": { "readOnlyHint": true },
      "inputSchema": {
        "type": "object",
        "properties": { "productId": { "type": "string" } },
        "required": ["productId"]
      }
    },
    {
      "name": "addToCart",
      "description": "Add a product to the shopping cart with quantity",
      "annotations": { "readOnlyHint": false, "idempotentHint": false },
      "inputSchema": {
        "type": "object",
        "properties": {
          "productId": { "type": "string" },
          "quantity": { "type": "integer", "minimum": 1 }
        },
        "required": ["productId"]
      }
    },
    {
      "name": "checkout",
      "description": "Initiate checkout for the current cart",
      "annotations": { "readOnlyHint": false, "confirmationRequired": true },
      "inputSchema": {
        "type": "object",
        "properties": { "shippingMethod": { "type": "string" } }
      }
    }
  ]
}

"/search": {
  "get": {
    "operationId": "searchProducts",
    "description": "Search the product catalog by keyword. Returns matching products with name, price, and availability. Use this when the user asks to find or browse products.",
    "parameters": [{
      "name": "q",
      "in": "query",
      "description": "Full-text search query, e.g. 'red running shoes'. Matched against product name and description.",
      "schema": { "type": "string" }
    }],
    "responses": { "200": { "description": "List of matching products" } }
  }
}

# Certbot (Let's Encrypt) quick setup:
sudo certbot --nginx -d yoursite.com -d www.yoursite.com

# Nginx HTTPS config:
server {
  listen 443 ssl;
  ssl_certificate /etc/letsencrypt/live/yoursite.com/fullchain.pem;
  ssl_certificate_key /etc/letsencrypt/live/yoursite.com/privkey.pem;
}

# Nginx microcaching example:
proxy_cache_path /tmp/cache levels=1:2 keys_zone=ai:10m max_size=1g;
proxy_cache_valid 200 1m;
add_header X-Cache-Status $upstream_cache_status;

// Next.js App Router (server component by default):
export default async function Page() {
  const data = await fetchProducts();
  return <ProductList items={data} />;
}

// Or with getServerSideProps (Pages Router):
export async function getServerSideProps() {
  const data = await fetchProducts();
  return { props: { data } };
}
